(()=>{'use strict';const D=window.MOTION_PRODUCTION,M=window.MotionProductionModel,$=id=>document.getElementById(id),canvas=$('stage'),ctx=canvas.getContext('2d'),images=new Map();let role=window.NAHIDA_NORMAL||D.roles[0],action='idle',frame=0,playing=true,continuous=false,last=0,ready=false,fxFrame=20,fxPlaying=false;
const options=()=>({outcome:$('outcome').value,distance:+$('distance').value});
function total(){const o=options();return continuous?M.flow.reduce((n,a)=>n+M.duration(role,a,o.outcome,o.distance),0):M.duration(role,action,o.outcome,o.distance);}
function reset(){frame=0;last=0;$('scrub').max=total()-1;updateButtons();}
function updateButtons(){for(const b of $('roles').children)b.classList.toggle('active',b.dataset.key===role.key);for(const b of $('actions').children)b.classList.toggle('active',!continuous&&b.dataset.action===action);$('flow').classList.toggle('active',continuous);$('title').textContent=role.name+' · '+(continuous?'连续动作流程':M.names[action]);$('details').textContent=role.notes.join('\n')+'\n独立姿势 '+role.frames.length+' 张；共享池峰值 '+role.pool+' 个矩形\n图元数据 '+role.dataBytes+' 字节；gzip '+role.gzipBytes+' 字节（运输数据，不代表千星可直接解压）\n原图、拟合图、事件模型均独立保存。未修改正式战斗。';}
for(const r of D.roles){const b=document.createElement('button');b.textContent=r.name;b.dataset.key=r.key;b.onclick=()=>{role=r;$('actorScale').value=(r.key==='nahida-normal-v2'||r.visualKey==='klee')?120:100;reset()};$('roles').append(b);}for(const[k,name]of Object.entries(M.names)){const b=document.createElement('button');b.textContent=name;b.dataset.action=k;b.onclick=()=>{action=k;continuous=false;reset()};$('actions').append(b);}
function actor(r,id,x,y,dir=1){const f=r.frames.find(f=>f.id===id),img=images.get(f.png);if(!img)return;ctx.save();ctx.translate(x,y);const scale=r===role?+$('actorScale').value/100:1;ctx.scale(dir*scale,scale);ctx.imageSmoothingEnabled=false;if($('silhouette').checked)ctx.filter='brightness(0) invert(1)';ctx.drawImage(img,-f.pixelAnchor[0]*f.displayScale,-f.pixelAnchor[1]*f.displayScale,img.width*f.displayScale,img.height*f.displayScale);ctx.restore();if($('anchors').checked){ctx.strokeStyle='#7edfd0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-8,y);ctx.lineTo(x+8,y);ctx.moveTo(x,y-8);ctx.lineTo(x,y+8);ctx.stroke();}}
function draw(){const o=options(),current=continuous?M.flowAt(role,frame,o.outcome,o.distance):{action,frame},a=current.action,t=current.frame,state=M.sample(role,a,t,o.outcome,o.distance),dir=+$('direction').value,base=dir===1?290:810,enemy=base+dir*o.distance,floor=425;ctx.clearRect(0,0,1100,540);const g=ctx.createLinearGradient(0,0,0,540);g.addColorStop(0,'#101928');g.addColorStop(1,'#2e3849');ctx.fillStyle=g;ctx.fillRect(0,0,1100,540);ctx.fillStyle='#39434c';ctx.beginPath();ctx.moveTo(0,floor);ctx.lineTo(1100,floor);ctx.lineTo(1100,520);ctx.lineTo(0,520);ctx.fill();ctx.strokeStyle='#6e7b8b';ctx.beginPath();ctx.moveTo(0,floor);ctx.lineTo(1100,floor);ctx.stroke();for(let x=0;x<1100;x+=100){ctx.beginPath();ctx.moveTo(x,floor);ctx.lineTo((x-550)*1.2+550,520);ctx.stroke();}
let dy=0,dx=0;if(a==='jump')dy=-Math.sin(Math.PI*t/M.duration(role,a))*145;if(a==='airA')dy=-110;if(a==='airHurt')dy=-80;if(a==='walk')dx=Math.sin(t/32*Math.PI*2)*22;if($('fxView').value!=='only')actor(role,state.pose,base+dir*dx,floor+dy,dir);
const other=D.roles.find(r=>r.key===(role.key==='diluc'?'keqing':'diluc')),victim=state.victim,vid=M.pose(other,victim,0);if($('fxView').value!=='only')actor(other,vid,enemy,floor,-dir);
const move=role.design.moves[a];if($('fx').checked&&$('fxMode').value==='legacy'&&move&&window.ProbeFX){const confirmed=a!=='Q'||state.phase==='命中演出'||state.phase==='终击结算 / 收招';if(confirmed){ctx.save();ctx.translate(base,floor);ctx.scale(dir,1);try{window.ProbeFX.draw({ctx,move,frame:t,role:{key:role.visualKey||role.key,design:role.design},model:window.ProbeModel,low:false,action:a,contact:{hit:state.damage>0||state.phase==='命中演出',blocked:state.victim==='guard'},distance:o.distance,motion:window.MotionStudy});}catch(e){$('loadStatus').textContent='特效绘制异常：'+e.message;}ctx.restore();}}
const hs=role.height*+$('actorScale').value/100,mode=$('fxMode').value,sock=$('fxSocket').value,local=window.EffectLab.socket(state.pose,hs,sock),world=sock==='world',target=sock==='target';let sx=world?550:target?enemy:base+dir*dx+dir*local[0],sy=world?floor-100:target?floor-other.height*.55:floor+dy+local[1];sx+=dir*+$('fxX').value;sy+=+$('fxY').value;
if($('fx').checked&&(mode==='independent'||mode==='compact'&&move)){const et=mode==='independent'?fxFrame:Math.max(0,t-move.startup+10),contact=mode==='independent'?$('fxContact').value:state.victim==='guard'?'guard':state.damage||state.phase==='命中演出'?'hit':'none';window.EffectLab.draw(ctx,{type:$('fxType').value,frame:et,x:sx,y:sy,dir,scale:+$('fxScale').value/100,colorKey:role.visualKey||role.key,contact,layer:$('fxLayer').value});}
if($('socketGuides').checked&&mode!=='off'){ctx.strokeStyle='#e7c979';ctx.beginPath();ctx.moveTo(sx-6,sy);ctx.lineTo(sx+6,sy);ctx.moveTo(sx,sy-6);ctx.lineTo(sx,sy+6);ctx.stroke();}
if($('attackGuides').checked){for(const[y,label]of [[floor-125,'上段视觉参考'],[floor-48,'下段视觉参考']]){ctx.strokeStyle='#e4cb7a77';ctx.setLineDash([5,6]);ctx.beginPath();ctx.moveTo(base-55,y);ctx.lineTo(enemy+55,y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#c9b488';ctx.font='12px sans-serif';ctx.fillText(label,base-70,y-5);}}
$('actorScaleValue').textContent=$('actorScale').value+'%';$('fxReadout').textContent=`特效逻辑帧 ${Math.floor(fxFrame)} / 60 · 绑定 ${sock} · 等比缩放 ${$('actorScale').value}%（预览）· 不改变伤害/判定；具体特效待讨论。`;
ctx.fillStyle='#e6d6b4';ctx.font='18px sans-serif';ctx.fillText(role.name+' · '+M.names[a],24,35);ctx.fillStyle='#acbdce';ctx.font='13px sans-serif';ctx.fillText('固定战斗视角 · 60Hz事件模型 · 素材候选',24,60);ctx.fillText('对手距离 '+o.distance+' / 结果 '+{hit:'命中',guard:'防住',whiff:'打空'}[o.outcome],24,85);if(state.damage){ctx.fillStyle='#f3c888';ctx.font='22px sans-serif';ctx.fillText('伤害 '+state.damage,enemy-35,135);}const f=role.frames.find(f=>f.id===state.pose);$('readout').textContent=`${M.names[a]} / ${state.phase} · 逻辑帧 ${Math.floor(t)} · 姿势 ${state.pose} · 图元 ${f.rectCount} · 伤害 ${state.damage}`;$('scrub').value=Math.floor(frame);}
function tick(now){if(last&&fxPlaying&&ready){fxFrame=(fxFrame+(now-last)/1000*60*+$('speed').value)%60;$('fxScrub').value=Math.floor(fxFrame);}if(last&&playing&&ready){frame+=(now-last)/1000*60*+$('speed').value;if(frame>=total())frame=0;}last=now;if(ready)draw();requestAnimationFrame(tick);}
$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'暂停':'播放'};$('restart').onclick=reset;$('step').onclick=()=>{playing=false;$('play').textContent='播放';frame=Math.min(total()-1,Math.floor(frame)+1)};$('flow').onclick=()=>{continuous=true;reset()};$('scrub').oninput=()=>{playing=false;$('play').textContent='播放';frame=+$('scrub').value};$('outcome').onchange=reset;$('distance').oninput=reset;
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>{const text=JSON.stringify({version:D.version,status:D.status,role,options:options(),productionCombatChanged:false},null,2);$('exportText').value=text;$('exportPreview').hidden=false;download(new Blob([text],{type:'application/json'}),role.key+'-motion-candidate.json')};$('shot').onclick=()=>canvas.toBlob(b=>download(b,role.key+'-'+action+'.png'));
$('scaleOriginal').onclick=()=>{$('actorScale').value=100};$('scalePreview').onclick=()=>{$('actorScale').value=120};$('fxPlay').onclick=()=>{fxPlaying=!fxPlaying;$('fxPlay').textContent=fxPlaying?'暂停特效':'播放特效'};$('fxReset').onclick=()=>{fxFrame=0};$('fxScrub').oninput=()=>{fxFrame=+$('fxScrub').value;fxPlaying=false;$('fxPlay').textContent='播放特效'};$('fxExport').onclick=()=>download(new Blob([JSON.stringify({version:window.EffectLab.version,role:role.key,pose:continuous?M.sample(role,M.flowAt(role,frame,options().outcome,options().distance).action,M.flowAt(role,frame,options().outcome,options().distance).frame,options().outcome,options().distance).pose:M.pose(role,action,frame,options().outcome,options().distance),type:$('fxType').value,socket:$('fxSocket').value,offset:[+$('fxX').value,+$('fxY').value],scale:+$('fxScale').value/100,actorPreviewScale:+$('actorScale').value/100,approximateSocket:true,productionCombatChanged:false},null,2)],{type:'application/json'}),role.key+'-fx-binding.json');
reset();Promise.all(D.roles.flatMap(r=>r.frames).map(f=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images.set(f.png,img);resolve()};img.onerror=()=>reject(Error(f.png));img.src=f.png;}))).then(()=>{ready=true;$('loadStatus').textContent='素材已载入：五位样板、納西妲新版，第一组凯亚、可莉、烟绯。'}).catch(e=>{$('loadStatus').textContent='加载失败：'+e.message});requestAnimationFrame(tick);
})();
